--
-- Table structure for table `etf_holdings`
--

DROP TABLE IF EXISTS `etf_holdings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `etf_holdings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `etf_id` int(10) unsigned NOT NULL,
  `stock_id` int(10) unsigned DEFAULT NULL,
  `holding_name` varchar(255) NOT NULL,
  `holding_ticker` varchar(20) DEFAULT NULL,
  `weight` decimal(10,4) DEFAULT NULL,
  `shares` bigint(20) DEFAULT NULL,
  `sector` varchar(120) DEFAULT NULL,
  `country` varchar(120) DEFAULT NULL,
  `position` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_holding_etf` (`etf_id`),
  KEY `idx_holding_stock` (`stock_id`),
