INSERT INTO `faqs` VALUES (1,'home',NULL,'מה זה xbt.co.il?','xbt.co.il הוא פורטל פיננסי מקיף בעברית המספק מידע על מניות, ETF, אג\"ח, מדדים, קריפטו, סקטורים, מדריכים והשוואות בשוק ההון בארה\"ב ובהונג קונג.',0,1,'2026-05-30 14:57:57','2026-05-30 14:57:57'),(2,'home',NULL,'האם המידע באתר מהווה ייעוץ השקעות?','המידע באתר נועד למטרות מידע ולימוד בלבד ואינו מהווה ייעוץ השקעות, שיווק השקעות, המלצה או תחליף לייעוץ מקצועי המותאם לצרכיו האישיים של כל אדם.',1,1,'2026-05-30 14:57:57','2026-05-30 14:57:57'),(3,'home',NULL,'אילו שווקים מכוסים באתר?','האתר מתמקד בשוק ההון בארה\"ב ובבורסת הונג קונג, וכולל מגוון רחב של סוגי נכסים.',2,1,'2026-05-30 14:57:57','2026-05-30 14:57:57'),(4,'home',NULL,'כיצד ניתן לחפש מניה או נכס?','ניתן להשתמש במנוע החיפוש בראש העמוד כדי למצוא מניות, ETF, מדדים, מונחים ומדריכים במהירות.',3,1,'2026-05-30 14:57:57','2026-05-30 14:57:57'),(5,'home',NULL,'האם השימוש באתר בחינם?','כן, כל תכני המידע והמדריכים באתר זמינים לשימוש חופשי.',4,1,'2026-05-30 14:57:57','2026-05-30 14:57:57');
