DROP TABLE IF EXISTS `stock_financials`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `stock_financials` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `stock_id` int(10) unsigned NOT NULL,
  `fiscal_year` smallint(6) NOT NULL,
  `fiscal_period` varchar(10) NOT NULL DEFAULT 'FY',
  `revenue` bigint(20) DEFAULT NULL,
  `gross_profit` bigint(20) DEFAULT NULL,
  `operating_income` bigint(20) DEFAULT NULL,
  `net_income` bigint(20) DEFAULT NULL,
  `eps` decimal(12,4) DEFAULT NULL,
  `ebitda` bigint(20) DEFAULT NULL,
  `total_assets` bigint(20) DEFAULT NULL,
  `total_liabilities` bigint(20) DEFAULT NULL,
  `total_equity` bigint(20) DEFAULT NULL,
  `free_cash_flow` bigint(20) DEFAULT NULL,
  `operating_cash_flow` bigint(20) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_fin` (`stock_id`,`fiscal_year`,`fiscal_period`),
  CONSTRAINT `fk_fin_stock` FOREIGN KEY (`stock_id`) REFERENCES `stocks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

